// The wave field, defined once and shared bit-for-bit between:
//   - JS   (waves.js):           so floating objects (board, camera clamp, spray,
//                               jumping fish) sit exactly on the shader's surface
//   - GLSL (via glslWaveChunk): so the ocean mesh is displaced by the same math
//
// Each wave is a directional sine:  h += amp * sin(dot(dir, p) * k - omega * t + phase)
// with k = 2*pi/lambda and omega = k * speed (deep-water-ish dispersion).

export const WAVES = [
  { dir: [1, 0], lambda: 30, speed: 2.4, amp: 1.5, phase: 0.0 },          // the swell the pelican rides
  { dir: [1, 0], lambda: 15, speed: 2.4, amp: 0.5, phase: -1.1 },         // harmonic: sharpens the crest
  { dir: [0.83, 0.56], lambda: 22, speed: 1.9, amp: 0.55, phase: 2.1 },   // crossing secondary swell
  { dir: [0.94, -0.34], lambda: 11, speed: 1.6, amp: 0.26, phase: 0.7 },  // wind chop
  { dir: [0.6, -0.8], lambda: 7, speed: 1.4, amp: 0.14, phase: 4.0 },     // finer chop
];

const TAU = Math.PI * 2;
for (const w of WAVES) {
  const len = Math.hypot(w.dir[0], w.dir[1]) || 1;
  w.dx = w.dir[0] / len;
  w.dz = w.dir[1] / len;
  w.k = TAU / w.lambda;
  w.om = w.k * w.speed;
}

export const SWELL = WAVES[0];

export function waveHeight(x, z, t) {
  let h = 0;
  for (let i = 0; i < WAVES.length; i++) {
    const w = WAVES[i];
    h += w.amp * Math.sin((w.dx * x + w.dz * z) * w.k - w.om * t + w.phase);
  }
  return h;
}

// Analytic surface normal (unit, y-up).
export function waveNormal(x, z, t, out) {
  let gx = 0;
  let gz = 0;
  for (let i = 0; i < WAVES.length; i++) {
    const w = WAVES[i];
    const c = w.amp * w.k * Math.cos((w.dx * x + w.dz * z) * w.k - w.om * t + w.phase);
    gx += w.dx * c;
    gz += w.dz * c;
  }
  return out.set(-gx, 1, -gz).normalize();
}

// Format a number as a clean GLSL float literal (always has a decimal point).
function fmt(n) {
  let s = n.toFixed(6).replace(/(\.\d*?)0+$/, '$1');
  if (s.endsWith('.')) s = s.slice(0, -1);
  if (!/[.eE]/.test(s)) s += '.0';
  return s === '-0.0' ? '0.0' : s;
}

// Emits GLSL functions waveH(vec2 p, float t) and waveGrad(vec2 p, float t)
// generated from the exact same constants used by the JS functions above.
export function glslWaveChunk() {
  let hf = 'float waveH(vec2 p, float t) {\n  float h = 0.0;\n';
  let gf = 'vec2 waveGrad(vec2 p, float t) {\n  vec2 g = vec2(0.0);\n';
  for (const w of WAVES) {
    const th = `dot(vec2(${fmt(w.dx)}, ${fmt(w.dz)}), p) * ${fmt(w.k)} - ${fmt(w.om)} * t + (${fmt(w.phase)})`;
    hf += `  h += ${fmt(w.amp)} * sin(${th});\n`;
    gf += `  g += vec2(${fmt(w.dx)}, ${fmt(w.dz)}) * (${fmt(w.amp * w.k)} * cos(${th}));\n`;
  }
  hf += '  return h;\n}\n\n';
  gf += '  return g;\n}\n';
  return hf + gf;
}

import * as THREE from 'three';

// All "assets" in this scene are generated in code (the packaged page must run
// offline with no network requests), so textures are drawn to canvases here.

export function makeGlowTexture(stops, size = 128) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  for (const [offset, color] of stops) grad.addColorStop(offset, color);
  g.fillStyle = grad;
  g.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeCloudTexture(size = 256) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const g = c.getContext('2d');
  for (let i = 0; i < 16; i++) {
    const x = size * (0.2 + 0.6 * Math.random());
    const y = size * (0.3 + 0.4 * Math.random());
    const r = size * (0.07 + 0.15 * Math.random());
    const grad = g.createRadialGradient(x, y, 0, x, y, r);
    grad.addColorStop(0, 'rgba(255,250,244,0.55)');
    grad.addColorStop(0.6, 'rgba(255,244,236,0.22)');
    grad.addColorStop(1, 'rgba(255,240,230,0)');
    g.fillStyle = grad;
    g.fillRect(0, 0, size, size);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

import * as THREE from 'three';
import { PALETTE } from './theme.js';
import { makeGlowTexture } from './textures.js';

// Gradient sky dome with a hot sun disc + glow, all in one shader.
// The dome is parented to the "scenery rig" that follows the rider, so the
// horizon and sun stay put like a genuinely distant backdrop.
export function createSky(sunDir) {
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      uZenith: { value: new THREE.Color(PALETTE.zenith) },
      uHorizon: { value: new THREE.Color(PALETTE.horizon) },
      uSun: { value: new THREE.Color(PALETTE.sun) },
      uSunDir: { value: sunDir.clone() },
    },
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uZenith;
      uniform vec3 uHorizon;
      uniform vec3 uSun;
      uniform vec3 uSunDir;
      varying vec3 vDir;
      void main() {
        vec3 d = normalize(vDir);
        float h = max(d.y, 0.0);
        vec3 col = mix(uHorizon, uZenith, pow(h, 0.55));
        float s = max(dot(d, normalize(uSunDir)), 0.0);
        col += uSun * (pow(s, 900.0) * 3.5 + pow(s, 80.0) * 0.5 + pow(s, 7.0) * 0.25 + pow(s, 2.0) * 0.06);
        float below = smoothstep(0.0, 0.10, -min(d.y, 0.0));
        col = mix(col, uHorizon, below);
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(520, 40, 24), mat);
  mesh.frustumCulled = false;
  return mesh;
}

// Soft additive sprite layered over the shader sun for a cheap bloom feel.
export function createSunSprite(sunDir) {
  const tex = makeGlowTexture([
    [0.0, 'rgba(255,250,240,1)'],
    [0.16, 'rgba(255,236,200,0.95)'],
    [0.4, 'rgba(255,205,150,0.45)'],
    [0.7, 'rgba(255,185,130,0.12)'],
    [1.0, 'rgba(255,180,125,0)'],
  ]);
  const mat = new THREE.SpriteMaterial({
    map: tex,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    fog: false,
  });
  const sp = new THREE.Sprite(mat);
  sp.scale.set(150, 150, 1);
  sp.position.copy(sunDir).multiplyScalar(430);
  return sp;
}

import * as THREE from 'three';
import { PALETTE } from './theme.js';
import { glslWaveChunk } from './waves.js';

// The ocean: one big plane whose vertices are displaced by the shared wave
// field. Normals come from the analytic gradient, plus tiny fragment-level
// ripple normals for sparkle. Foam appears on crests and the steep swell face;
// distance fades into the same warm haze as the sky horizon.
export function createOcean(sunDir) {
  const geo = new THREE.PlaneGeometry(560, 560, 380, 380);
  geo.rotateX(-Math.PI / 2);

  const uniforms = {
    uTime: { value: 0 },
    uSunDir: { value: sunDir.clone() },
    uCamPos: { value: new THREE.Vector3() },
    uDeep: { value: new THREE.Color(PALETTE.waterDeep) },
    uShallow: { value: new THREE.Color(PALETTE.waterShallow) },
    uSkyTint: { value: new THREE.Color(PALETTE.waterSky) },
    uSun: { value: new THREE.Color(PALETTE.sun) },
    uFog: { value: new THREE.Color(PALETTE.fog) },
  };

  const mat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: /* glsl */ `
      uniform float uTime;
      varying vec3 vWorld;
      varying vec3 vN;
      varying float vH;
      ${glslWaveChunk()}
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        float h = waveH(wp.xz, uTime);
        wp.y += h;
        vec2 g = waveGrad(wp.xz, uTime);
        vN = normalize(vec3(-g.x, 1.0, -g.y));
        vH = h;
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uSunDir;
      uniform vec3 uCamPos;
      uniform vec3 uDeep;
      uniform vec3 uShallow;
      uniform vec3 uSkyTint;
      uniform vec3 uSun;
      uniform vec3 uFog;
      varying vec3 vWorld;
      varying vec3 vN;
      varying float vH;
      void main() {
        vec2 p = vWorld.xz;
        float t = uTime;
        vec3 N = normalize(vN);

        // fine ripples: normals only (too small to displace geometry)
        float th1 = dot(vec2(0.85, 0.53), p) * 2.4166 - 2.6583 * t;
        float th2 = dot(vec2(0.28, -0.96), p) * 3.6959 - 3.6959 * t + 1.7;
        float th3 = dot(vec2(-0.60, 0.80), p) * 6.9813 - 6.2831 * t + 3.9;
        vec2 g = vec2(0.0);
        g += vec2(0.85, 0.53) * (0.045 * 2.4166 * cos(th1));
        g += vec2(0.28, -0.96) * (0.030 * 3.6959 * cos(th2));
        g += vec2(-0.60, 0.80) * (0.018 * 6.9813 * cos(th3));
        N = normalize(N + vec3(-g.x, 0.0, -g.y) * 1.5);

        vec3 V = normalize(uCamPos - vWorld);
        float fres = pow(1.0 - max(dot(N, V), 0.0), 3.0);
        vec3 col = mix(uDeep, uShallow, clamp((vH + 1.3) * 0.32, 0.0, 1.0));
        col = mix(col, uSkyTint, clamp(fres * 0.65, 0.0, 1.0));

        // sun glitter
        vec3 R = reflect(-normalize(uSunDir), N);
        float sparkle = 0.55 + 0.45 * sin(th1 * 3.7 + th2 * 2.9);
        col += uSun * pow(max(dot(R, V), 0.0), 150.0) * (1.4 + 2.2 * sparkle);

        // foam: noisy mask on crests, extra streaks on the steep face
        float n = sin(p.x * 0.55 + p.y * 0.35 - t * 0.9) * sin(p.y * 0.62 - p.x * 0.28 + t * 0.7);
        n += 0.6 * sin(p.x * 1.31 - p.y * 0.77 + t * 1.3);
        float crest = smoothstep(1.28, 1.95, vH);
        float steep = clamp(length(vN.xz) * 1.8, 0.0, 1.0);
        float foam = crest * clamp(0.30 + 0.55 * n, 0.0, 1.0) + crest * steep * 0.55;
        col = mix(col, vec3(0.93, 0.97, 0.96), clamp(foam, 0.0, 1.0) * 0.85);

        // warm haze toward the horizon (matches the sky)
        float dist = distance(uCamPos, vWorld);
        col = mix(col, uFog, smoothstep(80.0, 235.0, dist));

        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  });

  const mesh = new THREE.Mesh(geo, mat);
  mesh.frustumCulled = false;
  return { mesh, uniforms };
}

import * as THREE from 'three';
import { PALETTE } from './theme.js';

// The star of the show: a pelican standing on a longboard, built entirely from
// primitives. The root group ("board") is positioned and oriented by the app
// each frame to sit on the wave; update() handles all the posing:
// S-carving lean, crouch pumping, balance wing-shimmies with occasional flap
// bursts, gulping pouch, tail wag, head tracking (it watches the fish), and a
// sagged leash line from the tail plug to its ankle.

const X_AXIS = new THREE.Vector3(1, 0, 0);
const _v1 = new THREE.Vector3();
const _v2 = new THREE.Vector3();
const _v3 = new THREE.Vector3();
const _q1 = new THREE.Quaternion();
const _q2 = new THREE.Quaternion();
const _e1 = new THREE.Euler();

function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color: new THREE.Color(color), roughness: 0.62, ...opts });
}

// Smooth in-out bump: 0 -> 1 -> 0 once every `period` seconds, lasting `dur`.
function pulse(t, period, dur, phase = 0) {
  const x = ((((t / period + phase) % 1) + 1) % 1) * period;
  if (x >= dur) return 0;
  const u = x / dur;
  return Math.sin(u * Math.PI) ** 2;
}

export function createPelican() {
  const board = new THREE.Group(); // root: placed on the water by the app
  const deckY = 0.193;

  // deck height of the hull at a given x (hull radius * vertical squash)
  const deckAt = (x) => {
    const u = (x + 1.65) / 3.5;
    const taper = Math.sin(Math.PI * THREE.MathUtils.clamp(u, 0, 1) ** 0.9) ** 0.62;
    return 0.42 * 0.46 * taper;
  };

  // ── the longboard ──────────────────────────────────────────────
  const hullPts = [];
  for (let i = 0; i <= 30; i++) {
    const u = i / 30;
    const taper = Math.sin(Math.PI * u ** 0.9) ** 0.62;
    hullPts.push(new THREE.Vector2(Math.max(0.002, 0.46 * taper), -1.65 + 3.5 * u));
  }
  const hullGeo = new THREE.LatheGeometry(hullPts, 28);
  hullGeo.rotateZ(-Math.PI / 2); // length along +X (forward)
  const hull = new THREE.Mesh(hullGeo, mat(PALETTE.board, { roughness: 0.35 }));
  hull.scale.set(1, 0.42, 0.8); // flatten + narrow the circular cross-section
  board.add(hull);

  const matPaint = { roughness: 0.4 };
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(1.7, 0.02, 0.15), mat(PALETTE.stripe, matPaint));
  stripe.position.set(0.05, 0.183, 0);
  board.add(stripe);
  for (const zz of [-0.105, 0.105]) {
    const pin = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.016, 0.03), mat(PALETTE.pinstripe, matPaint));
    pin.position.set(0.05, 0.181, zz);
    board.add(pin);
  }
  const patchN = new THREE.Mesh(new THREE.CircleGeometry(0.11, 20), mat(PALETTE.stripe, matPaint));
  patchN.rotation.x = -Math.PI / 2;
  patchN.position.set(1.42, deckAt(1.42) + 0.005, 0);
  board.add(patchN);
  const patchT = new THREE.Mesh(new THREE.CircleGeometry(0.13, 20), mat(PALETTE.fin, matPaint));
  patchT.rotation.x = -Math.PI / 2;
  patchT.position.set(-1.42, deckAt(-1.42) + 0.005, 0);
  board.add(patchT);

  const fin = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.34, 0.05), mat(PALETTE.fin, { roughness: 0.5 }));
  fin.position.set(-1.12, -0.26, 0);
  fin.rotation.z = 0.38; // raked back
  board.add(fin);

  // fake contact shadow under the bird
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.5, 24),
    new THREE.MeshBasicMaterial({ color: 0x39220f, transparent: true, opacity: 0.15, depthWrite: false })
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0.02, deckY + 0.006, 0);
  shadow.scale.set(1.5, 1.15, 1);
  board.add(shadow);

  // anchors: spray emitters + leash plug
  const nose = new THREE.Object3D();
  nose.position.set(1.85, 0.05, 0);
  board.add(nose);
  const railL = new THREE.Object3D();
  railL.position.set(0.55, 0.08, 0.34);
  board.add(railL);
  const railR = new THREE.Object3D();
  railR.position.set(0.55, 0.08, -0.34);
  board.add(railR);
  const leashTail = new THREE.Object3D();
  leashTail.position.set(-1.5, 0.1, 0.12);
  board.add(leashTail);

  // ── the pelican ────────────────────────────────────────────────
  const pel = new THREE.Group();
  pel.position.set(0.02, deckY - 0.03, 0); // feet on the deck
  board.add(pel);

  const matWhite = mat(PALETTE.pelicanWhite);
  const matDark = mat(PALETTE.pelicanDark, { roughness: 0.75 });
  const matBeak = mat(PALETTE.beak, { roughness: 0.45 });
  const matPouch = mat(PALETTE.pouch, { roughness: 0.55 });
  const matJaw = mat(PALETTE.jaw, { roughness: 0.5 });
  const matFoot = mat(PALETTE.foot, { roughness: 0.55 });
  const matTuft = mat(PALETTE.tuft, { roughness: 0.85 });

  const body = new THREE.Group();
  body.position.y = 0.72;
  pel.add(body);

  const torso = new THREE.Mesh(new THREE.SphereGeometry(0.5, 24, 18), matWhite);
  torso.scale.set(1.28, 0.94, 0.84);
  body.add(torso);
  const chest = new THREE.Mesh(new THREE.SphereGeometry(0.34, 20, 14), matWhite);
  chest.scale.set(1.2, 0.95, 0.9);
  chest.position.set(0.32, -0.12, 0);
  body.add(chest);

  // tail fan
  const tail = new THREE.Group();
  tail.position.set(-0.6, 0.06, 0);
  tail.rotation.z = -0.45;
  body.add(tail);
  const featherGeo = new THREE.BoxGeometry(0.46, 0.018, 0.1);
  featherGeo.translate(-0.23, 0, 0);
  const tipGeo = new THREE.BoxGeometry(0.16, 0.02, 0.1);
  tipGeo.translate(-0.08, 0, 0);
  for (let i = -2; i <= 2; i++) {
    const p = new THREE.Group();
    p.rotation.y = i * 0.16;
    p.rotation.z = -0.03 * Math.abs(i);
    p.add(new THREE.Mesh(featherGeo, matWhite));
    const tip = new THREE.Mesh(tipGeo, matDark);
    tip.position.set(-0.4, 0, 0);
    p.add(tip);
    tail.add(p);
  }

  // S-curved neck + head
  const neckCurve = new THREE.QuadraticBezierCurve3(
    new THREE.Vector3(0.26, 0.16, 0),
    new THREE.Vector3(0.6, 0.62, 0),
    new THREE.Vector3(0.5, 0.94, 0)
  );
  body.add(new THREE.Mesh(new THREE.TubeGeometry(neckCurve, 14, 0.095, 10), matWhite));
  const neckBase = new THREE.Mesh(new THREE.SphereGeometry(0.15, 14, 10), matWhite);
  neckBase.position.set(0.26, 0.16, 0);
  body.add(neckBase);

  const head = new THREE.Group();
  head.position.set(0.5, 0.94, 0);
  body.add(head);
  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.2, 20, 16), matWhite);
  skull.scale.set(1.12, 1.0, 0.9);
  head.add(skull);

  const tuft = new THREE.Group();
  head.add(tuft);
  const tuftGeo = new THREE.BoxGeometry(0.18, 0.03, 0.045);
  tuftGeo.translate(-0.09, 0, 0);
  for (const [dx, dz, rz] of [[-0.08, 0.03, -0.85], [-0.12, 0, -1.1], [-0.08, -0.03, -0.85]]) {
    const f = new THREE.Mesh(tuftGeo, matTuft);
    f.position.set(dx, 0.17, dz);
    f.rotation.z = rz;
    tuft.add(f);
  }

  for (const s of [1, -1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.031, 12, 10), mat(PALETTE.eye, { roughness: 0.25 }));
    eye.position.set(0.1, 0.05, s * 0.155);
    head.add(eye);
    const glint = new THREE.Mesh(new THREE.SphereGeometry(0.009, 8, 6), new THREE.MeshBasicMaterial({ color: 0xffffff }));
    glint.position.set(0.118, 0.07, s * 0.166);
    head.add(glint);
  }

  // the famous beak: upper mandible + hinged jaw with a stretchy pouch
  const beak = new THREE.Group();
  beak.position.set(0.185, 0, 0);
  beak.rotation.z = -0.07;
  head.add(beak);
  const upperGeo = new THREE.CylinderGeometry(0.016, 0.058, 0.8, 10);
  upperGeo.rotateZ(-Math.PI / 2);
  const upper = new THREE.Mesh(upperGeo, matBeak);
  upper.position.set(0.4, 0.02, 0);
  beak.add(upper);
  const hook = new THREE.Mesh(new THREE.ConeGeometry(0.02, 0.08, 8), matBeak);
  hook.position.set(0.815, 0, 0);
  hook.rotation.z = -Math.PI / 2 - 0.5;
  beak.add(hook);
  const jaw = new THREE.Group();
  jaw.position.set(0.02, -0.035, 0);
  beak.add(jaw);
  const mandible = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.018, 0.07), matJaw);
  mandible.position.set(0.31, 0, 0);
  jaw.add(mandible);
  const pouch = new THREE.Mesh(new THREE.SphereGeometry(0.16, 18, 14), matPouch);
  pouch.scale.set(2.3, 1.0, 0.8);
  pouch.position.set(0.28, -0.07, 0);
  jaw.add(pouch);

  // legs + big webbed feet, staggered like a proper surf stance
  const toeGeo = new THREE.BoxGeometry(0.1, 0.016, 0.045);
  let backFoot = null;
  for (const [fx, fz] of [[0.3, 0.05], [-0.3, -0.05]]) {
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.048, 0.27, 10), matFoot);
    leg.position.set(fx, 0.165, fz);
    pel.add(leg);
    const foot = new THREE.Group();
    foot.position.set(fx, 0.035, fz);
    pel.add(foot);
    const web = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.02, 0.24), matFoot);
    web.position.set(0.05, 0.006, 0);
    foot.add(web);
    for (const [tz, ry] of [[-0.07, 0.45], [0, 0], [0.07, -0.45]]) {
      const toe = new THREE.Mesh(toeGeo, matFoot);
      toe.position.set(0.14, 0.006, tz);
      toe.rotation.y = ry;
      foot.add(toe);
    }
    if (fx < 0) backFoot = foot;
  }
  const ankle = new THREE.Object3D();
  ankle.position.set(0, 0.06, 0.03);
  backFoot.add(ankle);

  // wings: shoulder -> flap pivot -> arm -> elbow -> forearm -> hand with
  // white secondaries and dark primaries, held half-open for balance
  const wings = [];
  for (const s of [1, -1]) {
    const shoulder = new THREE.Group();
    shoulder.position.set(0.02, 0.18, s * 0.32);
    shoulder.rotation.y = -s * 0.55; // swept back
    body.add(shoulder);
    const flap = new THREE.Group();
    shoulder.add(flap);
    const patch = new THREE.Mesh(new THREE.SphereGeometry(0.11, 14, 10), matWhite);
    patch.scale.set(1.35, 0.75, 1);
    flap.add(patch);
    const armGeo = new THREE.CapsuleGeometry(0.075, 0.4, 6, 12);
    armGeo.rotateX((s * Math.PI) / 2);
    const arm = new THREE.Mesh(armGeo, matWhite);
    arm.position.set(0, 0, s * 0.24);
    flap.add(arm);
    const elbow = new THREE.Group();
    elbow.position.set(0, 0, s * 0.5);
    flap.add(elbow);
    const foreGeo = new THREE.CapsuleGeometry(0.058, 0.34, 6, 12);
    foreGeo.rotateX((s * Math.PI) / 2);
    const forearm = new THREE.Mesh(foreGeo, matWhite);
    forearm.position.set(0, 0, s * 0.22);
    elbow.add(forearm);
    for (let j = 0; j < 3; j++) {
      const p = new THREE.Group();
      p.position.set(0, -0.02, s * (0.08 + 0.13 * j));
      p.rotation.y = -s * (0.04 + 0.11 * j);
      const g = new THREE.BoxGeometry(0.06, 0.012, 0.4);
      g.translate(0, 0, s * 0.2);
      p.add(new THREE.Mesh(g, matWhite));
      elbow.add(p);
    }
    const hand = new THREE.Group();
    hand.position.set(0, 0, s * 0.45);
    elbow.add(hand);
    const primLens = [0.4, 0.48, 0.54, 0.5, 0.42];
    for (let i = 0; i < 5; i++) {
      const p = new THREE.Group();
      p.rotation.y = -s * (0.1 + 0.17 * i);
      p.rotation.x = -s * 0.05 * i;
      const g = new THREE.BoxGeometry(0.07, 0.014, primLens[i]);
      g.translate(0, 0, (s * primLens[i]) / 2);
      p.add(new THREE.Mesh(g, matDark));
      hand.add(p);
    }
    wings.push({ s, shoulder, flap, elbow });
  }

  // leash: sagged polyline from tail plug to ankle, updated each frame
  const LEASH_N = 14;
  const leashArr = new Float32Array(LEASH_N * 3);
  const leashGeo = new THREE.BufferGeometry();
  leashGeo.setAttribute('position', new THREE.BufferAttribute(leashArr, 3).setUsage(THREE.DynamicDrawUsage));
  const leash = new THREE.Line(
    leashGeo,
    new THREE.LineBasicMaterial({ color: new THREE.Color(PALETTE.leash), transparent: true, opacity: 0.9 })
  );
  leash.frustumCulled = false;
  board.add(leash);

  function update(ctx) {
    const t = ctx.t;
    const dt = ctx.dt;

    // stance sway + body language
    pel.rotation.y = 0.14 * Math.sin(0.13 * t) + ctx.lean * 0.12;
    body.position.y = 0.72 + 0.03 * Math.sin(2.2 * t) - ctx.crouch * 0.1;
    body.rotation.z = -0.16 - ctx.crouch * 0.1 + ctx.lean * 0.3;
    body.rotation.x = ctx.lean * 0.38; // twist into the turn

    // wings: idle shimmer + periodic takeoff-style flap bursts
    const burst = pulse(t, 8.5, 1.9, 0.35);
    const flapA = 0.32 + 0.05 * Math.sin(1.4 * t) + burst * 0.5 * Math.sin(11 * t);
    for (const w of wings) {
      w.flap.rotation.x = -w.s * flapA;
      w.elbow.rotation.x = w.s * (0.3 + burst * 0.28 * Math.sin(11 * t - 0.9));
      w.shoulder.rotation.y = -w.s * (0.55 + Math.abs(ctx.lean) * 0.18);
    }

    // gulping pouch
    const gulp = pulse(t, 7.3, 1.3, 0.6);
    jaw.rotation.z = -0.55 * gulp;
    pouch.scale.set(2.3 * (1 + 0.1 * gulp), 1.0 * (1 + 0.55 * gulp), 0.8 * (1 + 0.16 * gulp));

    // head: track the jumping fish, otherwise idle around
    if (ctx.fishWorld) {
      head.getWorldPosition(_v1);
      head.parent.getWorldQuaternion(_q1).invert();
      _v2.copy(ctx.fishWorld).sub(_v1).normalize().applyQuaternion(_q1);
      const ang = Math.acos(THREE.MathUtils.clamp(_v2.x, -1, 1));
      if (ang > 1.15) {
        // clamp how far the neck can turn
        _v3.crossVectors(X_AXIS, _v2);
        if (_v3.lengthSq() < 1e-8) _v3.set(0, 1, 0);
        else _v3.normalize();
        _q2.setFromAxisAngle(_v3, 1.15);
      } else {
        _q2.setFromUnitVectors(X_AXIS, _v2);
      }
    } else {
      _q2.setFromEuler(_e1.set(0.05 * Math.sin(1.6 * t), -ctx.carve * 0.5, 0.07 * Math.sin(1.1 * t) + gulp * 0.22));
    }
    head.quaternion.slerp(_q2, 1 - Math.exp(-6 * dt));

    tail.rotation.y = -ctx.carve * 0.35 + 0.07 * Math.sin(2.0 * t);
    tuft.rotation.z = 0.05 * Math.sin(3.1 * t);

    // leash: sagged arc between tail plug and ankle, in board space
    board.updateMatrixWorld(true);
    ankle.getWorldPosition(_v1);
    board.worldToLocal(_v1);
    leashTail.getWorldPosition(_v2);
    board.worldToLocal(_v2);
    for (let i = 0; i < LEASH_N; i++) {
      const u = i / (LEASH_N - 1);
      leashArr[i * 3] = _v2.x + (_v1.x - _v2.x) * u;
      leashArr[i * 3 + 1] = _v2.y + (_v1.y - _v2.y) * u - Math.sin(Math.PI * u) * 0.2;
      leashArr[i * 3 + 2] = _v2.z + (_v1.z - _v2.z) * u;
    }
    leashGeo.attributes.position.needsUpdate = true;
  }

  return { board, update, nose, railL, railR };
}

import * as THREE from 'three';
import { PALETTE } from './theme.js';
import { waveHeight } from './waves.js';
import { makeCloudTexture } from './textures.js';

// ── spray: a pooled point cloud for droplets off the nose/rails and splashes ──
export function createSpray() {
  const CAP = 800;
  const pos = new Float32Array(CAP * 3);
  const vel = new Float32Array(CAP * 3);
  const size = new Float32Array(CAP);
  const alpha = new Float32Array(CAP);
  const age = new Float32Array(CAP);
  const life = new Float32Array(CAP);
  let alive = 0;

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute('aSize', new THREE.BufferAttribute(size, 1).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1).setUsage(THREE.DynamicDrawUsage));
  geo.setDrawRange(0, 0);

  const mat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    uniforms: {
      uColor: { value: new THREE.Color(PALETTE.foam) },
      uScale: { value: 900 },
    },
    vertexShader: /* glsl */ `
      attribute float aSize;
      attribute float aAlpha;
      uniform float uScale;
      varying float vA;
      void main() {
        vA = aAlpha;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = aSize * uScale / max(0.3, -mv.z);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uColor;
      varying float vA;
      void main() {
        float d = length(gl_PointCoord - vec2(0.5));
        float a = (1.0 - smoothstep(0.18, 0.5, d)) * vA;
        if (a < 0.01) discard;
        gl_FragColor = vec4(uColor, a);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  });

  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;

  function copySlot(i, j) {
    for (let k = 0; k < 3; k++) {
      pos[i * 3 + k] = pos[j * 3 + k];
      vel[i * 3 + k] = vel[j * 3 + k];
    }
    size[i] = size[j];
    alpha[i] = alpha[j];
    age[i] = age[j];
    life[i] = life[j];
  }

  const _p = new THREE.Vector3();
  const _v = new THREE.Vector3();

  function spawn(p, v, s, l) {
    if (alive >= CAP) return;
    const i = alive++;
    pos[i * 3] = p.x;
    pos[i * 3 + 1] = p.y;
    pos[i * 3 + 2] = p.z;
    vel[i * 3] = v.x;
    vel[i * 3 + 1] = v.y;
    vel[i * 3 + 2] = v.z;
    size[i] = s;
    age[i] = 0;
    life[i] = l;
    alpha[i] = 0;
  }

  function burst(p, n, opts = {}) {
    const spread = opts.spread ?? 1.5;
    const up = opts.up ?? 2.6;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.random();
      _p.set(p.x + Math.cos(a) * r * spread, p.y, p.z + Math.sin(a) * r * spread);
      _v.set(Math.cos(a) * (0.4 + Math.random()), up * (0.4 + Math.random() * 0.8), Math.sin(a) * (0.4 + Math.random()));
      spawn(_p, _v, (opts.size ?? 0.15) * (0.6 + Math.random() * 0.9), (opts.life ?? 0.8) * (0.6 + Math.random() * 0.8));
    }
  }

  function update(dt, t) {
    let n = alive;
    for (let i = 0; i < n; ) {
      age[i] += dt;
      if (age[i] >= life[i]) {
        n--;
        if (i !== n) copySlot(i, n);
        continue;
      }
      vel[i * 3 + 1] -= 7.5 * dt; // gravity
      pos[i * 3] += vel[i * 3] * dt;
      pos[i * 3 + 1] += vel[i * 3 + 1] * dt;
      pos[i * 3 + 2] += vel[i * 3 + 2] * dt;
      if (pos[i * 3 + 1] < waveHeight(pos[i * 3], pos[i * 3 + 2], t) - 0.06) {
        n--; // droplet lands back in the sea
        if (i !== n) copySlot(i, n);
        continue;
      }
      alpha[i] = 0.85 * Math.sin(Math.min(age[i] / life[i], 1) * Math.PI);
      i++;
    }
    alive = n;
    geo.setDrawRange(0, n);
    geo.attributes.position.needsUpdate = true;
    geo.attributes.aSize.needsUpdate = true;
    geo.attributes.aAlpha.needsUpdate = true;
  }

  // pixel-perfect point sizing: worldSize * (h / (2*tan(fov/2))) / distance
  function setScale(height, fovDeg) {
    mat.uniforms.uScale.value = height / (2 * Math.tan((fovDeg * Math.PI) / 360));
  }

  return { points, spawn, burst, update, setScale };
}

// ── seagulls: three silhouettes circling on the rig ──
export function createGulls() {
  const group = new THREE.Group();
  const matBody = new THREE.MeshStandardMaterial({ color: new THREE.Color(PALETTE.gullBody), roughness: 0.85 });
  const matWing = new THREE.MeshStandardMaterial({ color: new THREE.Color(PALETTE.gullWing), roughness: 0.85 });
  const gulls = [];
  for (const [R, h, w, ph] of [[16, 4.5, 0.21, 0.0], [22, 6.8, 0.17, 2.1], [27, 9.0, 0.135, 4.2]]) {
    const g = new THREE.Group();
    g.rotation.order = 'YXZ';
    const bodyM = new THREE.Mesh(new THREE.CapsuleGeometry(0.05, 0.16, 4, 8), matBody);
    bodyM.rotation.x = Math.PI / 2;
    g.add(bodyM);
    const wings = [];
    for (const s of [1, -1]) {
      const p = new THREE.Group();
      p.position.set(s * 0.03, 0.01, 0);
      const wg = new THREE.BoxGeometry(0.3, 0.012, 0.09);
      wg.translate(s * 0.15, 0, 0);
      p.add(new THREE.Mesh(wg, matWing));
      g.add(p);
      wings.push(p);
    }
    const tailM = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.01, 0.1), matWing);
    tailM.position.set(0, 0, -0.12);
    g.add(tailM);
    group.add(g);
    gulls.push({ g, wings, R, h, w, ph });
  }

  function update(t) {
    for (const u of gulls) {
      const a = u.w * t + u.ph;
      const bob = Math.sin(0.5 * t + u.ph) * 0.7;
      const vy = 0.35 * Math.cos(0.5 * t + u.ph);
      u.g.position.set(Math.cos(a) * u.R, u.h + bob, Math.sin(a) * u.R);
      u.g.rotation.y = Math.atan2(-Math.sin(a), Math.cos(a)); // fly along the tangent
      u.g.rotation.x = THREE.MathUtils.clamp(-vy * 0.8, -0.35, 0.35);
      u.g.rotation.z = -0.4; // banked into the circle
      const f = Math.sin(9 * t + u.ph * 3) * 0.55 - 0.1;
      u.wings[0].rotation.z = f;
      u.wings[1].rotation.z = -f;
    }
  }

  return { group, update };
}

// ── clouds: soft canvas sprites drifting on the rig ──
export function createClouds() {
  const group = new THREE.Group();
  const tex = makeCloudTexture();
  const clouds = [];
  for (let i = 0; i < 9; i++) {
    const m = new THREE.SpriteMaterial({
      map: tex,
      color: 0xffe9d8,
      transparent: true,
      opacity: 0.35 + Math.random() * 0.35,
      depthWrite: false,
    });
    const sp = new THREE.Sprite(m);
    const ang = (i / 9) * Math.PI * 2 + Math.random() * 0.6;
    const rad = 80 + Math.random() * 80;
    sp.position.set(Math.cos(ang) * rad, 16 + Math.random() * 26, Math.sin(ang) * rad);
    const w = 26 + Math.random() * 34;
    sp.scale.set(w, w * 0.42, 1);
    group.add(sp);
    clouds.push({ sp, vx: 0.2 + Math.random() * 0.35 });
  }
  function update(dt) {
    for (const c of clouds) {
      c.sp.position.x += c.vx * dt;
      if (c.sp.position.x > 170) c.sp.position.x = -170;
    }
  }
  return { group, update };
}

// ── fish: one brave fish leaps out of the sea now and then ──
export function createFishFX() {
  const group = new THREE.Group();
  const matFish = new THREE.MeshStandardMaterial({ color: new THREE.Color(PALETTE.fish), roughness: 0.45 });
  const matFin = new THREE.MeshStandardMaterial({ color: new THREE.Color('#e0743a'), roughness: 0.6 });
  const fish = new THREE.Group();
  fish.visible = false;
  const bodyM = new THREE.Mesh(new THREE.SphereGeometry(0.13, 14, 10), matFish);
  bodyM.scale.set(2.1, 0.85, 0.55);
  fish.add(bodyM);
  const tailF = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.16, 0.11), matFin);
  tailF.position.set(-0.3, 0, 0);
  fish.add(tailF);
  const dorsal = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.07, 0.02), matFin);
  dorsal.position.set(-0.02, 0.1, 0);
  fish.add(dorsal);
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0x101014 });
  for (const s of [1, -1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.018, 8, 6), eyeMat);
    eye.position.set(0.17, 0.03, s * 0.06);
    fish.add(eye);
  }
  group.add(fish);

  let jump = null;
  let nextJump = 4.0;
  const activePos = new THREE.Vector3();
  const _p = new THREE.Vector3();

  function update(dt, t, pelican, spray) {
    if (!jump && t >= nextJump) {
      const x = pelican.x + 5 + Math.random() * 7;
      const z = pelican.z + (Math.random() - 0.5) * 10;
      jump = { t0: t, x, z, vx: -0.5 - Math.random() * 0.8, vz: (pelican.z - z) * 0.2, vy: 5.2, dur: 1.25 };
      spray.burst(_p.set(x, waveHeight(x, z, t) + 0.05, z), 16, { up: 2.4, spread: 0.9, size: 0.13, life: 0.7 });
    }
    if (jump) {
      const tau = t - jump.t0;
      const x = jump.x + jump.vx * tau;
      const z = jump.z + jump.vz * tau;
      const y = waveHeight(x, z, t) + jump.vy * tau - 4.9 * tau * tau;
      fish.visible = true;
      fish.position.set(x, y, z);
      fish.rotation.z = 0.5 - 7 * tau; // dazed somersault
      fish.rotation.y = 0.4 * Math.sin(3 * tau);
      activePos.set(x, y, z);
      if (tau >= jump.dur || y < waveHeight(x, z, t) - 0.3) {
        spray.burst(_p.set(x, waveHeight(x, z, t) + 0.05, z), 14, { up: 1.8, spread: 0.7, size: 0.11, life: 0.55 });
        jump = null;
        nextJump = t + 6 + Math.random() * 7;
        fish.visible = false;
      }
    }
  }

  return { group, update, active: () => (jump ? activePos : null) };
}

import * as THREE from 'three';
import { PALETTE } from './theme.js';
import { waveHeight, waveNormal, SWELL } from './waves.js';
import { createSky, createSunSprite } from './sky.js';
import { createOcean } from './ocean.js';
import { createPelican } from './pelican.js';
import { createSpray, createGulls, createClouds, createFishFX } from './effects.js';

// Phase of the main swell where the pelican rides: just past the crest, on the
// steep front face (slope ~20°), so it travels with the wave like a real surfer.
const THETA_FACE = 2.3;

function makeRenderer() {
  const r = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
  r.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  r.setSize(window.innerWidth, window.innerHeight);
  r.toneMapping = THREE.ACESFilmicToneMapping;
  r.toneMappingExposure = 1.12;
  r.setClearColor(new THREE.Color(PALETTE.fog));
  document.body.appendChild(r.domElement);
  return r;
}

let renderer;
try {
  renderer = makeRenderer();
} catch (err) {
  const fb = document.getElementById('fallback');
  if (fb) fb.style.display = 'grid';
  throw err;
}

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(new THREE.Color(PALETTE.fog), 80, 235); // for the standard-material props

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 1600);
camera.position.set(-20, 10, 26); // starts wide; swoops in for the first seconds

const sunDir = new THREE.Vector3(0.62, 0.2, -0.42).normalize();

const sunLight = new THREE.DirectionalLight(0xffd9a8, 2.6);
sunLight.position.copy(sunDir).multiplyScalar(60);
scene.add(sunLight);
scene.add(new THREE.HemisphereLight(0xffd2b0, 0x123b46, 0.9));

// The "scenery rig": sky, sun, clouds and gulls ride along with the pelican so
// the distant backdrop behaves like a genuinely far-away world.
const rig = new THREE.Group();
scene.add(rig);
rig.add(createSky(sunDir));
rig.add(createSunSprite(sunDir));
const clouds = createClouds();
rig.add(clouds.group);
const gulls = createGulls();
rig.add(gulls.group);

const ocean = createOcean(sunDir);
scene.add(ocean.mesh);

const pelican = createPelican();
scene.add(pelican.board);

const spray = createSpray();
scene.add(spray.points);

const fish = createFishFX();
scene.add(fish.group);

// scratch objects (reused every frame)
const _n = new THREE.Vector3();
const _f = new THREE.Vector3();
const _r = new THREE.Vector3();
const _u = new THREE.Vector3();
const _camPos = new THREE.Vector3();
const _look = new THREE.Vector3();
const _spawn = new THREE.Vector3();
const _vel = new THREE.Vector3();
const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const AXIS_X = new THREE.Vector3(1, 0, 0);
const AXIS_Z = new THREE.Vector3(0, 0, 1);
const camLook = new THREE.Vector3(12, 1, 2);

const clock = new THREE.Clock();
let t = 0;
let sprayAcc = 0;

function frame() {
  const dt = Math.min(clock.getDelta(), 0.05);
  t += dt;

  // ── kinematics: hold a fixed phase on the traveling swell while carving S-turns ──
  // swell phase: theta = k*x - omega*t + phase  =>  ride at theta = THETA_FACE
  const xBase = (THETA_FACE + SWELL.om * t - SWELL.phase) / SWELL.k;
  const x = xBase + 0.9 * Math.sin(0.19 * t + 0.6); // pumping down the face
  const z = 6.2 * Math.sin(0.12 * t) + 2.4 * Math.sin(0.29 * t + 1.7); // the carve
  const z1 = 6.2 * 0.12 * Math.cos(0.12 * t) + 2.4 * 0.29 * Math.cos(0.29 * t + 1.7); // z'
  const z2 = -6.2 * 0.0144 * Math.sin(0.12 * t) - 2.4 * 0.0841 * Math.sin(0.29 * t + 1.7); // z''
  const vx = SWELL.speed + 0.9 * 0.19 * Math.cos(0.19 * t + 0.6);
  const speed = Math.hypot(vx, z1);
  const carve = THREE.MathUtils.clamp(z1 / 0.9, -1, 1);
  const lean = THREE.MathUtils.clamp(z2 * 2.6, -0.6, 0.6); // heel into the turn
  const crouch = 0.5 + 0.5 * Math.sin(0.4 * t + 1.0);
  const y = waveHeight(x, z, t);

  pelican.board.position.set(x, y + 0.06, z);
  waveNormal(x, z, t, _n);
  _f.set(vx, 0, z1).normalize();
  _f.addScaledVector(_n, -_f.dot(_n)).normalize(); // travel dir, projected onto the surface
  _r.crossVectors(_f, _n).normalize();
  _u.crossVectors(_r, _f).normalize();
  _m.makeBasis(_f, _u, _r); // board: +X forward, +Y up (surface normal)
  pelican.board.quaternion.setFromRotationMatrix(_m);
  _q.setFromAxisAngle(AXIS_X, lean);
  pelican.board.quaternion.multiply(_q);
  _q.setFromAxisAngle(AXIS_Z, 0.05 * Math.sin(0.9 * t)); // gentle trim oscillation
  pelican.board.quaternion.multiply(_q);

  pelican.update({ t, dt, carve, lean, crouch, fishWorld: fish.active() });

  // ── spray off the nose, harder off the rail in turns ──
  sprayAcc += dt * (26 + Math.abs(lean) * 130 + Math.max(0, speed - 2.3) * 60 + Math.abs(carve) * 24);
  const emit = Math.floor(sprayAcc);
  sprayAcc -= emit;
  for (let i = 0; i < emit; i++) {
    pelican.nose.getWorldPosition(_spawn);
    _spawn.x += (Math.random() - 0.5) * 0.3;
    _spawn.z += (Math.random() - 0.5) * 0.3;
    _vel.set(
      vx * 0.28 + (Math.random() - 0.5) * 0.8,
      1.2 + Math.random() * 2.2,
      z1 * 0.28 - lean * 2.2 + (Math.random() - 0.5) * 1.4
    );
    spray.spawn(_spawn, _vel, 0.05 + Math.random() * 0.13, 0.45 + Math.random() * 0.55);
  }
  if (Math.abs(lean) > 0.22 && Math.random() < dt * 45) {
    // hard turn: fling a bucket off the outside rail
    (lean > 0 ? pelican.railR : pelican.railL).getWorldPosition(_spawn);
    _vel.set(vx * 0.2, 1.6 + Math.random() * 2, -lean * 3 + (Math.random() - 0.5));
    spray.spawn(_spawn, _vel, 0.08 + Math.random() * 0.16, 0.5 + Math.random() * 0.5);
  }
  spray.update(dt, t);

  fish.update(dt, t, pelican.board.position, spray);
